'use strict';
const byId = id => document.getElementById(id);
const esc = v => String(v ?? '').replace(/[&<>"']/g, x => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const money = p => 'Rs. ' + (Number(p || 0) / 100).toLocaleString('en-PK',{minimumFractionDigits:0,maximumFractionDigits:2});
const amountToPaisa = v => { const n=Number(v); if(!Number.isFinite(n)||n<=0||n>9999999999||Math.abs(n*100-Math.round(n*100))>0.00001)throw Error('Enter a valid positive amount with up to two decimal places.'); return Math.round(n*100); };
const today = () => new Date().toLocaleDateString('en-CA');
const GROUPS = window.STARTER_DATA.teams;
const INITIAL = {groups:GROUPS.map(x=>({...x})), members:window.STARTER_DATA.members.map(m=>({...m,group_id:m.teamId,is_group_lead:m.isGroupLead,is_team_lead:m.isTeamLead})), projects:window.STARTER_DATA.projects,ledger_entries:[],expense_shares:[],profiles:[]};
const cfg = window.PORTAL_CONFIG || {};
const connected = Boolean(cfg.apiKey && cfg.projectId && window.firebase);
const client = connected ? firebase.initializeApp(cfg) : null;
const auth = connected ? firebase.auth() : null;
const store = connected ? firebase.firestore() : null;
let db=structuredClone(INITIAL),user=null,profile=null,role=connected?'loading':'demo',authView='login',pendingEmail='',page='home',adminTab='entries',memberSearch='',groupFilter='all',mfa={factors:[],enrollment:null,challenge:null},loading=false,recovery=false,authScreen=false;
let watcher=null,poller=null,toastTimeout=null,authInitialized=false;
const isAdmin = () => role==='admin';
const isReader = () => ['admin','member','demo'].includes(role);
const mBy = id => db.members.find(m=>m.id===id);
const gBy = id => db.groups.find(g=>g.id===id);
const pBy = id => db.projects.find(p=>p.id===id);
const gId = m => m.group_id || m.teamId;
const gName = id => gBy(id)?.name || '—';
const mName = id => mBy(id)?.name || '—';
const pName = id => pBy(id)?.name || '—';
const activeEntries = () => db.ledger_entries.filter(e=>!e.voided_at);
const membersIn = id => id==='chassis'?db.members:db.members.filter(m=>gId(m)===id);
const leadBadges = m => `${m.is_team_lead||m.isTeamLead?'<span class="tag teamlead">Team Lead</span>':''}${m.is_group_lead||m.isGroupLead?'<span class="tag lead">Group Lead</span>':''}`;
const personHtml = m => `<span class="person-title"><span class="person-name">${esc(m.name)}</span>${leadBadges(m)}</span>`;
const initials = n => String(n||'??').split(/\s+/).slice(0,2).map(s=>s[0]||'').join('').toUpperCase();
const actionBtn=(label,action,cls='')=>`<button type="button" class="btn ${cls}" data-action="${esc(action)}">${label}</button>`;
const groupChoices = (includeShared=true) => db.groups.filter(g=>includeShared||!g.shared).map(g=>`<option value="${esc(g.id)}">${esc(g.name)}</option>`).join('');
const memberChoices = (selected='') => db.members.map(m=>`<option value="${esc(m.id)}" ${selected===m.id?'selected':''}>${esc(m.name)} · ${esc(m.enrollment)}</option>`).join('');
const projectChoices = () => '<option value="">No project</option>'+db.projects.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');
const rowMember = (m,stat) => `<tr><td class="name-cell"><div class="person-line"><span class="person-avatar">${esc(initials(m.name))}</span><div>${personHtml(m)}${m.enrollment?`<div class="small-sub">${esc(m.enrollment)}</div>`:''}</div></div></td><td>${esc(gBy(gId(m))?.code)}</td><td class="money deposit">${money(stat.deposits)}</td><td class="money expense">${money(stat.expenses)}</td><td class="money ${stat.balance<0?'negative':''}">${money(stat.balance)}</td><td>${actionBtn('Details','member:'+m.id,'btn-sm')}</td></tr>`;
function flash(message,error=false){const n=byId('notices');if(!n)return;clearTimeout(toastTimeout);n.innerHTML=`<div class="toast-area"><div class="toast ${error?'bad':''}">${esc(message)}</div></div>`;toastTimeout=setTimeout(()=>{n.innerHTML='';},5200);}
function calc(){
 const members=Object.fromEntries(db.members.map(m=>[m.id,{deposits:0,expenses:0,balance:0}]));
 const groups=Object.fromEntries(db.groups.map(g=>[g.id,{deposits:0,expenses:0,shares:0}]));
 const projects=Object.fromEntries(db.projects.map(p=>[p.id,{expenses:0}]));
 let deposits=0,expenses=0;
 const live=activeEntries();
 for(const e of live){const amt=Number(e.amount_paisa)||0;
  if(e.kind==='deposit') {deposits+=amt; if(members[e.member_id])members[e.member_id].deposits+=amt;const gr=gId(mBy(e.member_id)||{});if(groups[gr])groups[gr].deposits+=amt;}
  else {expenses+=amt;if(groups[e.group_id])groups[e.group_id].expenses+=amt;if(e.project_id&&projects[e.project_id])projects[e.project_id].expenses+=amt;}
 }
 for(const share of db.expense_shares){const e=live.find(x=>x.id===share.expense_id);if(!e)continue; const amt=Number(share.amount_paisa)||0; if(members[share.member_id])members[share.member_id].expenses+=amt; const group=gId(mBy(share.member_id)||{});if(groups[group])groups[group].shares+=amt;}
 for(const m of db.members)members[m.id].balance=members[m.id].deposits-members[m.id].expenses;
 return {members,groups,projects,deposits,expenses,balance:deposits-expenses,entries:live};
}
function sectionTitle(title,sub='',label='',actions=''){return `<div class="intro"><div>${label?`<div class="kicker">${esc(label)}</div>`:''}<h1>${esc(title)}</h1><p>${esc(sub)}</p></div><div class="action-row">${actions}</div></div>`;}
function statCard(label,value,sub,glyph){return `<div class="metric"><div class="metric-heading"><span class="metric-name">${esc(label)}</span><span class="metric-glyph">${glyph}</span></div><div class="metric-value">${esc(value)}</div><div class="metric-sub">${esc(sub)}</div></div>`;}
function notice(){if(role==='demo'||role==='guest')return `<div class="notice warning"><strong>Public roster preview.</strong> Member names are shown for reference. Balances shown here are not live records. ${connected?'Sign in with an approved account for the live ledger.':'Connect the secure database to activate accounts and transaction records.'}</div>`;return '';}
function teamLeads(){const leaders=db.members.filter(m=>m.is_team_lead||m.isTeamLead);return `<div class="leader-panel">${leaders.map(m=>`<div class="leader-chip">${personHtml(m)}<small>${esc(gName(gId(m)))}</small></div>`).join('')}</div>`;}
function groupTable(t){
 const rows=db.groups.map(g=>{const v=t.groups[g.id],count=membersIn(g.id).length; const leads=membersIn(g.id).filter(m=>m.is_group_lead||m.isGroupLead);
 return `<tr class="${g.shared?'shared':''}"><td class="group-cell"><div class="group-label"><span class="group-code">${esc(g.code)}</span><strong>${esc(g.name)}</strong></div><div class="small-sub">${g.shared?'Shared across all members':membersIn(g.id).map(personHtml).join('<span class="roster-dot">·</span>')}</div></td><td>${g.shared?'All '+count:count}</td><td class="money deposit">${g.shared?'—':money(v.deposits)}</td><td class="money expense">${money(v.expenses)}</td><td class="money">${g.shared?'—':money(v.shares)}</td><td>${actionBtn('Open','group:'+g.id,'btn-sm')}</td></tr>`;}).join('');
 return `<div class="table-scroll desktop-table"><table class="table"><thead><tr><th>Group</th><th>Members</th><th>Deposits</th><th>Group expenses</th><th>Member shares</th><th></th></tr></thead><tbody>${rows}<tr class="tfoot"><td>Total</td><td>${db.members.length}</td><td class="money">${money(t.deposits)}</td><td class="money">${money(t.expenses)}</td><td class="money">${money(t.expenses)}</td><td></td></tr></tbody></table></div><div class="mobile-cards">${db.groups.map(g=>{const v=t.groups[g.id],leads=membersIn(g.id).filter(m=>m.is_group_lead||m.isGroupLead);return `<button class="mobile-row" data-action="group:${esc(g.id)}"><div class="mobile-row-head"><span class="group-code">${esc(g.code)}</span><strong>${esc(g.name)}</strong><span class="more">›</span></div>${!g.shared?`<div class="group-mobile-roster">${membersIn(g.id).map(personHtml).join('')}</div>`:''}<div class="mobile-numbers"><div><span>Deposits</span><strong class="deposit">${g.shared?'—':money(v.deposits)}</strong></div><div><span>Expenses</span><strong class="expense">${money(v.expenses)}</strong></div></div><div class="mobile-small">${g.shared?'All '+db.members.length+' members charged':money(v.shares)+' allocated to this group’s members'}</div></button>`;}).join('')}<div class="mobile-totals"><strong>Totals</strong><span>Deposits ${money(t.deposits)}</span><span>Expenses ${money(t.expenses)}</span></div></div>`;
}
function memberTable(t,arr){const rows=arr.map(m=>rowMember(m,t.members[m.id])).join('');return `<div class="table-scroll desktop-table"><table class="table"><thead><tr><th>Member</th><th>Group</th><th>Deposits</th><th>Expenses</th><th>Balance</th><th></th></tr></thead><tbody>${rows}<tr class="tfoot"><td>All ${db.members.length} members</td><td></td><td>${money(t.deposits)}</td><td>${money(t.expenses)}</td><td>${money(t.balance)}</td><td></td></tr></tbody></table></div><div class="mobile-cards">${arr.map(m=>{const s=t.members[m.id];return `<button class="mobile-row" data-action="member:${esc(m.id)}"><div class="mobile-row-head"><span class="person-avatar">${esc(initials(m.name))}</span><div class="name-flex">${personHtml(m)}<div class="small-sub">${esc(gBy(gId(m))?.code)}${m.enrollment?' · '+esc(m.enrollment):''}</div></div><span class="more">›</span></div><div class="mobile-numbers"><div><span>Deposits</span><strong class="deposit">${money(s.deposits)}</strong></div><div><span>Expenses</span><strong class="expense">${money(s.expenses)}</strong></div></div><div class="mobile-small">Remaining: <strong>${money(s.balance)}</strong></div></button>`;}).join('')}<div class="mobile-totals"><strong>All-member totals</strong><span>Deposits ${money(t.deposits)}</span><span>Expenses ${money(t.expenses)}</span><span>Balance ${money(t.balance)}</span></div></div>`;}
function home(){const t=calc();const nonShared=db.groups.filter(g=>!g.shared), max=Math.max(1,...nonShared.map(g=>t.groups[g.id].expenses));const recent=[...t.entries].sort((a,b)=>b.entry_date.localeCompare(a.entry_date)).slice(0,5);
 return sectionTitle('Finance overview','One shared fund · '+db.members.length+' individual member ledgers · '+db.groups.length+' groups','TEAM FINANCE',isAdmin()?actionBtn('+ Record payment','admin:entries','btn-primary'):'')+notice()+`<div class="metrics">${statCard('Total deposits',money(t.deposits),'Contributions received','↗')}${statCard('Total expenses',money(t.expenses),'Shared across 26 members','↘')}${statCard('Remaining balance',money(t.balance),'Deposits minus expenses','◈')}${statCard('Roster members',String(db.members.length),'10 groups + shared chassis','♙')}</div><div class="grid-2"><section class="panel"><div class="panel-head"><div><h2>Group expenditure</h2><p>Amount spent by each technical group</p></div>${actionBtn('All groups','nav:groups','btn-sm')}</div><div class="panel-content"><div class="bar-list">${nonShared.map(g=>`<div class="bar-row"><strong>${esc(g.code)}</strong><div class="track"><div class="bar-fill" style="width:${Math.round(t.groups[g.id].expenses/max*100)}%"></div></div><span class="bar-amount">${money(t.groups[g.id].expenses)}</span></div>`).join('')}</div></div></section><section class="panel"><div class="panel-head"><div><h2>Recent transactions</h2><p>Latest deposits and expenses</p></div>${actionBtn('Full ledger','nav:ledger','btn-sm')}</div><div class="panel-content">${recent.length?recent.map(e=>`<div class="recent-item"><div><strong>${esc(e.note)}</strong><p>${esc(e.entry_date)} · ${e.kind==='deposit'?esc(mName(e.member_id)):esc(gName(e.group_id))}</p></div><strong class="${e.kind==='deposit'?'deposit':'expense'}">${e.kind==='deposit'?'+':'−'}${money(e.amount_paisa)}</strong></div>`).join(''):'<div class="empty">No transactions recorded yet.</div>'}</div></section></div><section class="panel"><div class="panel-head"><div><h2>Group records</h2><p>Deposits and group expenditure are shown separately. Every expense is allocated to all 26 members.</p></div></div>${groupTable(t)}<div class="tfoot-note">Group expenses show where money was spent. Member shares show the amount charged to the members of that group. Do not add member shares to group expenses again.</div></section><section class="panel"><div class="panel-head"><div><h2>Team leads</h2><p>Primary team contacts</p></div></div><div class="panel-content">${teamLeads()}</div></section>`;
}
function groupsPage(){const t=calc();return sectionTitle('Groups','All 10 technical groups and the shared Chassis group','GROUP RECORDS',isAdmin()?actionBtn('Add expense','admin:entries','btn-primary'):'')+`<section class="panel"><div class="panel-head"><div><h2>Group deposits and expenditure</h2><p>Every group expense is shared by all roster members.</p></div><span class="filter-pill">11 groups</span></div>${groupTable(t)}<div class="tfoot-note">The expenses column totals each recorded expense once. Chassis is a shared group. The member-shares column is an allocation breakdown and is not additional spending.</div></section>`;}
function membersPage(){const t=calc();let list=[...db.members];if(groupFilter!=='all')list=list.filter(m=>gId(m)===groupFilter);if(memberSearch.trim())list=list.filter(m=>`${m.name} ${m.enrollment}`.toLowerCase().includes(memberSearch.trim().toLowerCase()));return sectionTitle('Member accounts','Each member has a separate record of deposits, expenses and remaining balance','MEMBER RECORDS')+`<section class="panel"><div class="panel-head"><div><h2>Individual balances</h2><p>Expenses are divided among every member regardless of the group that paid.</p></div></div><div class="searchbar"><input id="member-search" placeholder="Search name or enrollment number" value="${esc(memberSearch)}" aria-label="Search members"><select id="member-group-filter" aria-label="Filter member group"><option value="all">All groups</option>${db.groups.filter(g=>!g.shared).map(g=>`<option value="${esc(g.id)}" ${groupFilter===g.id?'selected':''}>${esc(g.code)} · ${esc(g.name)}</option>`).join('')}</select></div>${memberTable(t,list)}<div class="tfoot-note">Totals at the bottom always cover the full roster, including when a filter is applied.</div></section>`;}
function projectsPage(){const t=calc();return sectionTitle('Projects','12 project records; project names and budgets can be updated by an administrator.','PROJECTS',isAdmin()?actionBtn('Edit projects','admin:projects','btn-primary'):'')+`<div class="project-grid">${db.projects.map(p=>{const amt=Number(p.budget_paisa),spent=t.projects[p.id].expenses,pct=amt?Math.min(100,Math.round(spent/amt*100)):0;return `<div class="project-tile"><span class="filter-pill">${esc(p.id.toUpperCase())}</span><div style="margin-top:13px"><strong>${esc(p.name)}</strong></div><div class="number">${money(spent)}</div><div class="small-sub">Expenses recorded</div><div class="project-progress"><span style="width:${pct}%"></span></div><div class="small-sub">Budget ${money(amt)} · Remaining ${money(amt-spent)}</div></div>`;}).join('')}</div>`;}
function ledgerPage(){const t=calc();const list=[...db.ledger_entries].sort((a,b)=>b.entry_date.localeCompare(a.entry_date)||b.created_at.localeCompare(a.created_at));return sectionTitle('Transaction ledger','Member deposits and group expenses are recorded in separate columns.','TRANSACTIONS',isAdmin()?actionBtn('+ New entry','admin:entries','btn-primary'):'')+`<section class="panel"><div class="panel-head"><div><h2>Account activity</h2><p>Only approved administrators can add or void entries.</p></div><span class="filter-pill">${t.entries.length} active entries</span></div><div class="table-scroll desktop-table"><table class="table"><thead><tr><th>Date</th><th>Description</th><th>Member / Group</th><th>Deposit</th><th>Expense</th><th>Status</th><th></th></tr></thead><tbody>${list.map(e=>`<tr><td>${esc(e.entry_date)}</td><td class="name-cell"><strong>${esc(e.note)}</strong>${e.project_id?`<div class="small-sub">${esc(pName(e.project_id))}</div>`:''}</td><td>${e.kind==='deposit'?esc(mName(e.member_id)):esc(gName(e.group_id))}</td><td class="money deposit">${e.kind==='deposit'&&!e.voided_at?money(e.amount_paisa):'—'}</td><td class="money expense">${e.kind==='expense'&&!e.voided_at?money(e.amount_paisa):'—'}</td><td>${e.voided_at?'<span class="tag void">Voided</span>':'<span class="tag ok">Recorded</span>'}</td><td>${isAdmin()&&!e.voided_at?actionBtn('Void','void:'+e.id,'btn-sm btn-danger'):''}</td></tr>`).join('')}<tr class="tfoot"><td colspan="3">Total active transactions</td><td>${money(t.deposits)}</td><td>${money(t.expenses)}</td><td colspan="2">Remaining ${money(t.balance)}</td></tr></tbody></table>${list.length?'':'<div class="empty">No transactions recorded yet.</div>'}</div><div class="mobile-cards">${list.map(e=>`<div class="mobile-row static"><div class="mobile-row-head"><strong>${esc(e.note)}</strong><span class="tag ${e.voided_at?'void':'ok'}">${e.voided_at?'Voided':e.kind==='deposit'?'Deposit':'Expense'}</span></div><div class="small-sub">${esc(e.entry_date)} · ${e.kind==='deposit'?esc(mName(e.member_id)):esc(gName(e.group_id))}</div><div class="mobile-numbers"><div><span>Deposit</span><strong class="deposit">${e.kind==='deposit'&&!e.voided_at?money(e.amount_paisa):'—'}</strong></div><div><span>Expense</span><strong class="expense">${e.kind==='expense'&&!e.voided_at?money(e.amount_paisa):'—'}</strong></div></div>${isAdmin()&&!e.voided_at?actionBtn('Void entry','void:'+e.id,'btn-sm btn-danger'):''}</div>`).join('')}<div class="mobile-totals"><strong>Totals</strong><span>Deposits ${money(t.deposits)}</span><span>Expenses ${money(t.expenses)}</span><span>Balance ${money(t.balance)}</span></div></div></section>`;}
function transactionForm(){return `<div class="grid-2"><section class="panel form-panel"><h2>Record a transaction</h2><p>Deposits are assigned to one member. Expenses are assigned to a group and automatically split among all 26 members.</p><form id="transaction-form" class="form-stack"><div class="field"><label for="entry-kind">Transaction type</label><select name="kind" id="entry-kind"><option value="deposit">Member deposit</option><option value="expense">Group expense</option></select></div><div id="entry-extra">${entryFields('deposit')}</div><div class="form-grid"><div class="field"><label>Amount (Rs.)</label><input type="number" name="amount" required min="0.01" step="0.01" placeholder="e.g. 2600"></div><div class="field"><label>Date</label><input type="date" name="entry_date" required value="${today()}"></div></div><div class="field"><label>Description</label><textarea name="note" maxlength="300" required placeholder="Payment purpose / expense detail"></textarea></div><button class="btn btn-primary" type="submit">Save transaction</button></form></section><section class="panel form-panel"><h2>Expense sharing</h2><p>Every expense is split equally between the 26 roster members, regardless of which group incurred it.</p><div class="form-note"><strong>Example</strong><br>Motor group expense: Rs. 5,200<br>Charge per member: Rs. 200<br>Overall expenditure: Rs. 5,200</div><p style="margin-top:16px">Individual deposits remain assigned to the member who paid. All calculations use whole paisa and preserve exact totals.</p></section></div>`;}
function entryFields(kind){if(kind==='deposit')return `<div class="field"><label>Member making the deposit</label><select name="member_id" required>${memberChoices()}</select></div>`;return `<div class="form-stack"><div class="field"><label>Group responsible for expense</label><select name="group_id" required>${groupChoices()}</select></div><div class="field"><label>Project (optional)</label><select name="project_id">${projectChoices()}</select></div></div>`;}
function accessTable(){return `<section class="panel"><div class="panel-head"><div><h2>Account requests</h2><p>Only approved administrators can approve an account.</p></div><span class="filter-pill">${db.profiles.filter(x=>!x.approved).length} pending</span></div><div class="table-scroll"><table class="table"><thead><tr><th>Name / Email</th><th>Requested role</th><th>Requested group</th><th>Access</th><th></th></tr></thead><tbody>${db.profiles.map(p=>`<tr><td class="name-cell"><strong>${esc(p.first_name)} ${esc(p.last_name)}</strong><div class="small-sub">${esc(p.email)}</div>${p.phone?`<div class="small-sub">Phone ${esc(p.phone)} · not verified</div>`:''}</td><td>${esc(p.requested_role)}</td><td>${esc(gName(p.requested_group_id))}</td><td><span class="tag ${p.approved?'ok':'pending'}">${p.approved?esc(p.role):'Pending'}</span><div class="small-sub">${esc(mName(p.member_id))}</div></td><td>${p.role==='owner'?'<span class="tiny">Owner</span>':actionBtn('Manage','access:'+p.user_id,'btn-sm')}</td></tr>`).join('')}</tbody></table></div></section>`;}
function adminPage(){if(!isAdmin())return '<div class="notice error">Administrator login required.</div>';
 const tabs=[['entries','Transactions'],['access','Approvals'],['members','Members'],['groups','Groups'],['projects','Projects']];
 let inner='';
 if(adminTab==='entries')inner=transactionForm();
 if(adminTab==='access')inner=accessTable();
 if(adminTab==='members')inner=`<section class="panel"><div class="panel-head"><div><h2>Member details</h2><p>Edit names, assigned group and leadership tags.</p></div></div><div class="table-scroll"><table class="table"><thead><tr><th>Member</th><th>Group</th><th></th></tr></thead><tbody>${db.members.map(m=>`<tr><td class="name-cell">${personHtml(m)}<div class="small-sub">${esc(m.enrollment)}</div></td><td>${esc(gName(gId(m)))}</td><td>${actionBtn('Edit','edit-member:'+m.id,'btn-sm')}</td></tr>`).join('')}</tbody></table></div></section>`;
 if(adminTab==='groups')inner=`<section class="panel"><div class="panel-head"><div><h2>Group names</h2><p>Expense sharing is not affected by renaming a group.</p></div></div><div class="table-scroll"><table class="table"><thead><tr><th>Group</th><th>Members</th><th></th></tr></thead><tbody>${db.groups.map(g=>`<tr><td class="group-cell">${esc(g.code)} · <strong>${esc(g.name)}</strong></td><td>${membersIn(g.id).length}</td><td>${actionBtn('Rename','edit-group:'+g.id,'btn-sm')}</td></tr>`).join('')}</tbody></table></div></section>`;
 if(adminTab==='projects')inner=`<section class="panel"><div class="panel-head"><div><h2>Project details</h2><p>12 project names and budgets.</p></div></div><div class="table-scroll"><table class="table"><thead><tr><th>Project</th><th>Budget</th><th></th></tr></thead><tbody>${db.projects.map(p=>`<tr><td><strong>${esc(p.name)}</strong></td><td>${money(p.budget_paisa)}</td><td>${actionBtn('Edit','edit-project:'+p.id,'btn-sm')}</td></tr>`).join('')}</tbody></table></div></section>`;
 return sectionTitle('Admin dashboard','Restricted to approved administrators.','ADMINISTRATION')+`<div class="tabs">${tabs.map(([id,label])=>`<button type="button" class="tab ${id===adminTab?'active':''}" data-action="tab:${id}">${label}</button>`).join('')}</div>`+inner;
}
function accountPage(){if(role==='guest'||role==='demo')return sectionTitle('Account access','Sign in to access your financial records','ACCOUNT',actionBtn('Member sign in','member-login','btn-primary')+actionBtn('Admin Portal','admin-portal'));return sectionTitle('My account','Registered account and security settings','ACCOUNT')+`<div class="grid-2"><section class="panel form-panel"><h2>Account details</h2><p>${esc(profile?.first_name||'')} ${esc(profile?.last_name||'')}</p><div class="form-note"><strong>${esc(user?.email||'Preview')}</strong><br>${isAdmin()?esc(profile.role==='owner'?'Owner':'Administrator'):'Team member'}${profile?.member_id?`<br>Linked member: ${esc(mName(profile.member_id))}`:''}</div><div class="form-actions" style="margin-top:18px">${connected?actionBtn('Sign out','logout','btn-dark'):actionBtn('Setup instructions','setup','btn-dark')}</div></section>${connected?`<section class="panel form-panel"><h2>Change password</h2><p>A password must contain at least 12 characters.</p><form id="password-change" class="form-stack"><div class="field"><label>New password</label><input name="password" type="password" autocomplete="new-password" minlength="12" required></div><button type="submit" class="btn btn-primary">Update password</button></form><button type="button" class="auth-link" data-action="send-reset">Send a password reset email instead</button></section>`:''}</div>`;}
function layout(){
 const items=[['home','Overview','⌂'],['groups','Groups','▦'],['members','Members','♙'],['projects','Projects','▤'],['ledger','Ledger','≡']];
 const menu=items.map(([key,label,icon])=>`<button type="button" class="nav-btn ${page===key?'active':''}" data-action="nav:${key}"><span class="nav-icon">${icon}</span>${label}</button>`).join('');
 const bottom=[items[0],items[1],items[2],items[4]];
 const adminSelected=page==='admin'&&isAdmin();
 const adminMenu=`<button type="button" class="nav-btn nav-admin ${adminSelected?'active':''}" data-action="admin-portal"><span class="nav-icon">▣</span>Admin Portal</button>`;
 const signin=role==='guest'?`<button class="btn btn-sm sign-in" type="button" data-action="member-login">Member sign in</button>`:'';
 const acct=role==='demo'||role==='guest'?`<button type="button" class="avatar" data-action="member-login" aria-label="Member sign in">?</button>`:`<button type="button" class="avatar" data-action="nav:account" aria-label="My account">${esc(initials(profile?.first_name||'Member'))}</button>`;
 const activePage=(!isAdmin()&&page==='admin')?'home':page;
 let content={home,groups:groupsPage,members:membersPage,projects:projectsPage,ledger:ledgerPage,admin:adminPage,account:accountPage}[activePage]?.()||home();
 byId('app').innerHTML=`<div class="shell"><aside class="rail"><div class="identity"><span class="brand-symbol">C</span><div><div class="brand-name">Collective</div><div class="brand-caption">Team Finance</div></div></div><div class="rail-label">Workspace</div><nav class="nav-stack">${menu}<div class="rail-divider"></div>${adminMenu}</nav><div class="rail-foot"><div class="rail-box"><strong>${esc(['demo','guest'].includes(role)?'Roster preview':'Shared ledger')}</strong>${esc(['demo','guest'].includes(role)?'Sign in for live financial records.':'Financial records are accessible to approved team members.')}</div></div></aside><div class="work-area"><header class="top"><div class="top-crumb">Workspace <strong>${esc(({home:'Overview',groups:'Groups',members:'Members',projects:'Projects',ledger:'Transactions',admin:'Administration',account:'Account'})[activePage]||'Overview')}</strong></div><div class="top-right">${signin}<button type="button" class="btn btn-sm header-admin ${adminSelected?'btn-primary':''}" data-action="admin-portal">▣ <span>Admin Portal</span></button><span class="mode-pill">${esc(isAdmin()?'Admin':role==='member'?'Member':'Preview')}</span>${acct}</div></header><main class="content">${content}</main></div></div><nav class="bottom-nav">${bottom.map(([key,label,icon])=>`<button type="button" class="bottom-btn ${page===key?'active':''}" data-action="nav:${key}"><span>${icon}</span>${label}</button>`).join('')}<button type="button" class="bottom-btn ${adminSelected?'active':''}" data-action="admin-portal"><span>▣</span>Admin</button></nav>`;
}
function modal(title,subtitle,body){byId('modal-root').innerHTML=`<div class="modal-backdrop" data-overlay="1"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-heading"><div><h2>${esc(title)}</h2><p>${esc(subtitle)}</p></div><button class="close" data-action="close" aria-label="Close dialog">×</button></div><div class="modal-body">${body}</div></div></div>`;}
function closeModal(){byId('modal-root').innerHTML='';}
function memberDetails(id){const m=mBy(id);if(!m)return;const t=calc(),s=t.members[id],items=[];for(const e of t.entries){if(e.kind==='deposit'&&e.member_id===id)items.push({e,label:'Deposit',amount:e.amount_paisa,kind:'deposit'});else if(e.kind==='expense'){const share=db.expense_shares.find(x=>x.expense_id===e.id&&x.member_id===id);if(share)items.push({e,label:gName(e.group_id),amount:share.amount_paisa,kind:'expense'});}}items.sort((a,b)=>b.e.entry_date.localeCompare(a.e.entry_date));modal(m.name,m.enrollment+' · '+gName(gId(m)),`<div class="detail-stats"><div class="detail-stat"><small>Deposits</small><strong class="deposit">${money(s.deposits)}</strong></div><div class="detail-stat"><small>Expenses allocated</small><strong class="expense">${money(s.expenses)}</strong></div><div class="detail-stat"><small>Remaining</small><strong>${money(s.balance)}</strong></div></div><div style="margin-bottom:16px">${personHtml(m)}</div><div class="table-scroll"><table class="table"><thead><tr><th>Date</th><th>Transaction</th><th>Deposit</th><th>Expense</th></tr></thead><tbody>${items.map(x=>`<tr><td>${esc(x.e.entry_date)}</td><td>${esc(x.e.note)}<div class="small-sub">${esc(x.label)}</div></td><td class="money deposit">${x.kind==='deposit'?money(x.amount):'—'}</td><td class="money expense">${x.kind==='expense'?money(x.amount):'—'}</td></tr>`).join('')}<tr class="tfoot"><td colspan="2">Total</td><td>${money(s.deposits)}</td><td>${money(s.expenses)}</td></tr></tbody></table>${items.length?'':'<div class="empty">No transactions yet.</div>'}</div>`);}
function groupDetails(id){const g=gBy(id);if(!g)return;const t=calc(),v=t.groups[id],ms=membersIn(id),expenses=t.entries.filter(e=>e.kind==='expense'&&e.group_id===id);modal(g.name,g.shared?'Shared group · every roster member':g.code+' · '+ms.length+' members',`<div class="detail-stats"><div class="detail-stat"><small>Deposits by members</small><strong>${g.shared?'—':money(v.deposits)}</strong></div><div class="detail-stat"><small>Group expenses</small><strong class="expense">${money(v.expenses)}</strong></div><div class="detail-stat"><small>Member shares</small><strong>${g.shared?'—':money(v.shares)}</strong></div></div><h3>Group members</h3><div class="form-note">${ms.map(personHtml).join('<span style="margin:0 7px;color:#a4b5ae">·</span>')}</div><h3 style="margin-top:22px">Expenses recorded by this group</h3>${expenses.map(e=>`<div class="recent-item"><div><strong>${esc(e.note)}</strong><p>${esc(e.entry_date)}</p></div><strong class="expense">${money(e.amount_paisa)}</strong></div>`).join('')||'<div class="empty">No expenses recorded yet.</div>'}`);}
function editMember(id){const m=mBy(id);if(!m||!isAdmin())return;modal('Edit member','Enrollment number '+m.enrollment,`<form id="edit-member" class="form-stack"><input type="hidden" name="id" value="${esc(id)}"><div class="field"><label>Full name</label><input name="name" value="${esc(m.name)}" minlength="2" maxlength="110" required></div><div class="field"><label>Group</label><select name="group_id">${db.groups.filter(g=>!g.shared).map(g=>`<option value="${esc(g.id)}" ${gId(m)===g.id?'selected':''}>${esc(g.name)}</option>`).join('')}</select></div><label class="field" style="display:flex;align-items:center;gap:9px"><input style="width:auto" type="checkbox" name="is_group_lead" ${m.is_group_lead?'checked':''}>Group Lead</label><label class="field" style="display:flex;align-items:center;gap:9px"><input style="width:auto" type="checkbox" name="is_team_lead" ${m.is_team_lead?'checked':''}>Team Lead</label><button class="btn btn-primary" type="submit">Save member details</button></form>`);}
function editGroup(id){const g=gBy(id);if(!g||!isAdmin())return;modal('Rename group',g.code,`<form id="edit-group" class="form-stack"><input name="id" type="hidden" value="${esc(id)}"><div class="field"><label>Group name</label><input name="name" required maxlength="180" minlength="2" value="${esc(g.name)}"></div><button type="submit" class="btn btn-primary">Save name</button></form>`);}
function editProject(id){const p=pBy(id);if(!p||!isAdmin())return;modal('Edit project',p.id.toUpperCase(),`<form id="edit-project" class="form-stack"><input name="id" type="hidden" value="${esc(id)}"><div class="field"><label>Project name</label><input name="name" value="${esc(p.name)}" required minlength="1" maxlength="130"></div><div class="field"><label>Budget in rupees</label><input name="budget" type="number" step="0.01" min="0" value="${Number(p.budget_paisa)/100}" required></div><button class="btn btn-primary" type="submit">Save project</button></form>`);}
function manageAccount(id){const p=db.profiles.find(q=>q.user_id===id);if(!p||!isAdmin())return;const isOwner=profile?.role==='owner';modal('Manage registration',p.first_name+' '+p.last_name+' · '+p.email,`<form id="approval-form" class="form-stack"><input type="hidden" name="user_id" value="${esc(id)}"><div class="form-note"><strong>Requested role:</strong> ${esc(p.requested_role)}<br><strong>Requested group:</strong> ${esc(gName(p.requested_group_id))}<br><strong>Current access:</strong> ${esc(p.role)} · ${p.approved?'Approved':'Pending'}</div>${p.role==='member'?`<div class="field"><label>Link to roster member</label><select name="member_id"><option value="">Select a member</option>${db.members.map(m=>`<option value="${esc(m.id)}" ${p.member_id===m.id?'selected':''}>${esc(m.name)} · ${esc(m.enrollment)}</option>`).join('')}</select></div><div class="form-actions"><button type="submit" class="btn btn-primary" name="allow" value="yes">Approve member</button><button type="submit" class="btn btn-danger" name="allow" value="no">Revoke / deny</button></div>`:'<div class="notice">This account has an administrator role.</div>'}</form>${isOwner&&p.role!=='owner'?`<hr style="border:0;border-top:1px solid #e5ece9;margin:21px 0"><h3>Owner controls</h3><p class="tiny muted">Approve and link this member first, then grant administrator access. Every administrator signs in with their own password.</p>${actionBtn(p.role==='admin'?'Remove admin role':'Grant admin role','admin-role:'+id,'btn-primary')}`:''}`);}
function adminPortal(){
 if(isAdmin()){page='admin';return nav('admin');}
 if(role==='member'){
  modal('Admin Portal','Administrator sign-in required',`<p class="portal-copy">You are signed in with a member account. The administrative dashboard requires an approved administrator account .</p><div class="form-actions">${actionBtn('Switch to admin account','switch-admin','btn-primary')}${actionBtn('Close','close')}</div>`);return;
 }
 if(role==='pending'||role==='mfa'){
  modal('Admin Portal','Verification required','<p class="portal-copy">Your account needs administrator approval before using the portal.</p>');return;
 }
 const disabled=!client;
 modal('Admin Portal',disabled?'Secure administrator access · setup required':'Secure administrator sign in',
  `${disabled?'<div class="notice warning">This is a local preview. Administrator login becomes available after the database and authentication service are configured.</div>':''}<form id="admin-login-form" class="form-stack"><div class="field"><label>Administrator email</label><input type="email" name="email" autocomplete="username" placeholder="admin@example.com" required ${disabled?'disabled':''}></div><div class="field"><label>Password</label><input type="password" name="password" autocomplete="current-password" required ${disabled?'disabled':''}></div><button type="submit" class="btn btn-primary btn-block" ${disabled?'disabled':''}>Continue securely</button></form><div class="auth-row portal-links">${actionBtn('Reset password','auth:forgot','btn-sm')}${actionBtn('Register an account','auth:signup','btn-sm')}</div><p class="tiny muted portal-copy">Member accounts require administrator approval. No email OTP is required.</p>`);
}

function authShell(content){byId('app').innerHTML=`<div class="auth-wrap"><section class="auth-brand"><div class="identity"><span class="brand-symbol">C</span><div><div class="brand-name">Collective</div><div class="brand-caption">Team Finance</div></div></div><div><h1>Every contribution. Every expense.</h1><p>Shared financial records for the Shell Eco Marathon team. Access is restricted to approved accounts.</p></div><div class="auth-foot">Private team workspace</div></section><main class="auth-main"><div class="auth-card">${content}</div></main></div>`;}
const authFields=(email='',password=true)=>`<div class="field"><label>Email address</label><input type="email" name="email" autocomplete="email" value="${esc(email)}" required></div>${password?'<div class="field"><label>Password</label><input type="password" name="password" autocomplete="current-password" required></div>':''}`;
function authPage(){if(authView==='signup'){
 authShell(`<h2>Register your account</h2><p>Create your account. An administrator must approve it before you can view finance records.</p><form id="register-form" class="form-stack"><div class="form-grid"><div class="field"><label>First name</label><input name="first_name" autocomplete="given-name" maxlength="70" required></div><div class="field"><label>Last name</label><input name="last_name" autocomplete="family-name" maxlength="70" required></div></div><div class="form-grid"><div class="field"><label>Team role</label><select name="requested_role" required><option>Member</option><option>Group Leader</option><option>Team Lead</option></select></div><div class="field"><label>Technical group</label><select name="group_id" required><option value="">Choose group</option>${GROUPS.filter(g=>!g.shared).map(g=>`<option value="${esc(g.id)}">${esc(g.name)}</option>`).join('')}</select></div></div><div class="field"><label>Email</label><input type="email" name="email" autocomplete="email" required></div><div class="field"><label>Phone number (optional)</label><input type="tel" name="phone" autocomplete="tel" placeholder="+92 3XX XXXXXXX" maxlength="25"><div class="hint">Optional contact number. No SMS verification required.</div></div><div class="form-grid"><div class="field"><label>Password</label><input type="password" name="password" minlength="12" autocomplete="new-password" required></div><div class="field"><label>Confirm password</label><input type="password" name="confirm" minlength="12" autocomplete="new-password" required></div></div><div class="form-actions"><button class="btn btn-primary btn-block" type="submit">Create account</button></div></form><button class="auth-link" data-action="auth:login">Already registered? Sign in</button>`);return;
 }

 if(authView==='forgot'){
 authShell(`<h2>Reset your password</h2><p>We'll send a secure password-reset link to your registered email.</p><form id="forgot-form" class="form-stack">${authFields('',false)}<button class="btn btn-primary btn-block" type="submit">Send reset link</button></form><button class="auth-link" data-action="auth:login">Back to sign in</button>`);return;
 }
 if(authView==='reset'){
 authShell(`<h2>Choose a new password</h2><p>Your reset link has been verified. Choose a password with at least 12 characters.</p><form class="form-stack" id="reset-form"><div class="field"><label>New password</label><input name="password" type="password" autocomplete="new-password" minlength="12" required></div><div class="field"><label>Confirm password</label><input name="confirm" type="password" autocomplete="new-password" minlength="12" required></div><button class="btn btn-primary btn-block" type="submit">Update password</button></form>`);return;
 }
 authShell(`<h2>Welcome back</h2><p>Sign in to view the shared finance ledger.</p><form id="login-form" class="form-stack">${authFields()}<div class="auth-row"><span></span><button type="button" class="auth-link" data-action="auth:forgot">Forgot password?</button></div><button class="btn btn-primary btn-block" type="submit">Sign in securely</button></form><div class="auth-row" style="margin-top:17px"><span class="tiny muted">New to the team?</span><button type="button" class="auth-link" data-action="auth:signup">Create member account</button></div>`);
}
function pendingPage(){authShell(`<h2>Approval pending</h2><p>Your account must be approved and linked to a roster member before you can access financial records.</p><div class="auth-note"><strong>${esc(user?.email)}</strong><br>${esc(profile?.first_name||'')} ${esc(profile?.last_name||'')}<br>Requested group: ${esc(gName(profile?.requested_group_id))}</div><button class="btn btn-primary btn-block" data-action="check-approval">Check approval status</button><button class="auth-link" data-action="logout">Sign out</button>`);}

function render(){if(role==='demo')return authPage();if(role==='loading'){byId('app').innerHTML='<div class="auth-wrap"><main class="auth-main"><div class="auth-card"><h2>Loading your account…</h2><p>Checking your secure session.</p></div></main></div>';return;}if(recovery){authView='reset';return authPage();}if(role==='guest')return authPage();if(role==='pending')return pendingPage();return layout();}
function nav(next){if(next==='admin'&&!isAdmin())return adminPortal();if(!['home','groups','members','projects','ledger','admin','account'].includes(next))return;page=next;render();window.scrollTo({top:0,behavior:'instant'});}
async function checkAuth(){
 const me=auth?.currentUser;
 if(!me){user=null;profile=null;role='guest';authView='login';page='home';render();return;}
 user={id:me.uid,email:me.email};
 const snap=await store.collection('users').doc(me.uid).get();
 profile=snap.exists ? {...snap.data(),user_id:me.uid} : null;
 if(!profile){role='pending';render();return;}
 if(!profile.approved){role='pending';render();return;}
 role=['admin','owner'].includes(profile.role)?'admin':'member';
 if(isAdmin() && page==='home')page='admin';
 await loadDatabase();startLive();render();
}
async function seedRoster(){
 if(!isAdmin())return;
 const meta=await store.collection('system').doc('roster').get();if(meta.exists)return;
 const batch=store.batch();
 for(const [key,items] of [['groups',INITIAL.groups],['members',INITIAL.members],['projects',INITIAL.projects]]){
  for(const item of items)batch.set(store.collection(key).doc(item.id),item);
 }
 batch.set(store.collection('system').doc('roster'),{seeded:true,seeded_by:user.id,seeded_at:firebase.firestore.FieldValue.serverTimestamp()});
 await batch.commit();
}
async function loadDatabase(){
 if(!store||!['member','admin'].includes(role)||loading)return;loading=true;
 try{
  const keys=['groups','members','projects','ledger_entries','expense_shares'];
  if(isAdmin())keys.push('users');
  const results=await Promise.all(keys.map(k=>store.collection(k).get()));
  keys.forEach((k,i)=>{const rows=results[i].docs.map(d=>({...d.data(),id:d.id}));if(k==='users')db.profiles=rows.map(x=>({...x,user_id:x.id}));else db[k]=rows;});
  if(isAdmin()&&!db.groups.length){await seedRoster();loading=false;return loadDatabase();}
  if(!isAdmin())db.profiles=[];
 }catch(e){console.error('Firestore loading failed',e);flash('Unable to load records: '+e.message,true);}finally{loading=false;}
}
function startLive(){
 if(watcher)return;
 watcher=store.collection('system').doc('revision').onSnapshot(async()=>{
  if(['admin','member'].includes(role)&&!loading){await loadDatabase();if(!byId('modal-root').children.length)render();}
 });
}
async function logout(){
 if(watcher){watcher();watcher=null;}
 await auth.signOut();user=null;profile=null;role='guest';authView='login';authScreen=false;page='home';closeModal();db=structuredClone(INITIAL);render();
}
async function touchRevision(batch){batch.set(store.collection('system').doc('revision'),{updatedAt:firebase.firestore.FieldValue.serverTimestamp(),by:user.id});}
async function runWrite(table,data,id){
 if(!isAdmin())throw Error('Administrator authentication is required.');
 const batch=store.batch();batch.update(store.collection(table).doc(id),data);await touchRevision(batch);await batch.commit();await loadDatabase();render();closeModal();
}

function busyForm(form,on=true){if(form){const b=form.querySelector('[type="submit"]');if(b){b.disabled=on;b.dataset.orig=b.dataset.orig||b.textContent;b.textContent=on?'Working…':b.dataset.orig;}}}
async function handleFormSubmit(e){const form=e.target;if(!(form instanceof HTMLFormElement))return;e.preventDefault();const F=new FormData(form);const v=k=>String(F.get(k)||'').trim();
 busyForm(form,true);
 try{
  if(form.id==='register-form'){
   if(v('password')!==v('confirm'))throw Error('Passwords do not match.');
   if(v('password').length<12)throw Error('Use at least 12 characters.');
   const cred=await auth.createUserWithEmailAndPassword(v('email').toLowerCase(),v('password'));
   const data={email:v('email').toLowerCase(),first_name:v('first_name'),last_name:v('last_name'),requested_role:v('requested_role'),requested_group_id:v('group_id'),phone:v('phone'),role:'member',approved:false,member_id:null,created_at:firebase.firestore.FieldValue.serverTimestamp()};
   try{await store.collection('users').doc(cred.user.uid).set(data);}catch(err){throw Error('Account created but profile could not be saved: '+err.message);}
   authScreen=false;await checkAuth();flash('Account created. Await administrator approval.');
  }else if(form.id==='admin-login-form'||form.id==='login-form'){
   await auth.signInWithEmailAndPassword(v('email'),v('password'));
   authScreen=false;if(form.id==='admin-login-form')page='admin';closeModal();await checkAuth();
   if(form.id==='admin-login-form'&&!isAdmin())flash('This account is not an approved administrator.',true);
  }else if(form.id==='forgot-form'){
   await auth.sendPasswordResetEmail(v('email'));
   flash('Password reset email sent.');authView='login';render();
  }else if(form.id==='password-change'||form.id==='reset-form'){
   if(v('password').length<12)throw Error('Use at least 12 characters.');
   if(form.id==='reset-form'&&v('password')!==v('confirm'))throw Error('Passwords do not match.');
   await auth.currentUser.updatePassword(v('password'));flash('Password changed.');await checkAuth();

  }else if(form.id==='transaction-form'){
   if(!isAdmin())throw Error('Administrator access required.');const kind=v('kind');const row={kind,amount_paisa:amountToPaisa(v('amount')),note:v('note'),entry_date:v('entry_date')};if(kind==='deposit')row.member_id=v('member_id');else{row.group_id=v('group_id');row.project_id=v('project_id')||null;}
   if(!row.note)throw Error('Enter a description.');const batch=store.batch();const entry=store.collection('ledger_entries').doc();batch.set(entry,{...row,created_by:user.id,created_at:firebase.firestore.FieldValue.serverTimestamp(),voided_at:null});
   if(kind==='expense'){
    const roster=db.members;if(!roster.length)throw Error('No members in roster.');
    const base=Math.floor(row.amount_paisa/roster.length),extra=row.amount_paisa%roster.length;
    roster.forEach((m,i)=>{const ref=store.collection('expense_shares').doc(entry.id+'_'+m.id);batch.set(ref,{expense_id:entry.id,member_id:m.id,amount_paisa:base+(i<extra?1:0)});});
   }
   await touchRevision(batch);await batch.commit();await loadDatabase();render();flash('Transaction recorded and expenses allocated.');
  }else if(form.id==='edit-member'){
   await runWrite('members',{name:v('name'),group_id:v('group_id'),is_group_lead:F.has('is_group_lead'),is_team_lead:F.has('is_team_lead')},v('id'));flash('Member updated.');
  }else if(form.id==='edit-group'){
   await runWrite('groups',{name:v('name')},v('id'));flash('Group updated.');
  }else if(form.id==='edit-project'){
   const budget=v('budget');const n=Number(budget);if(!Number.isFinite(n)||n<0)throw Error('Enter a valid budget.');const paisa=n===0?0:amountToPaisa(budget);await runWrite('projects',{name:v('name'),budget_paisa:paisa},v('id'));flash('Project updated.');
  }else if(form.id==='approval-form'){
   const submitter=e.submitter;const allow=submitter?.value==='yes';if(allow&&!v('member_id'))throw Error('Select the matching roster member first.');await runWrite('users',{approved:allow,member_id:allow?v('member_id'):null},v('user_id'));closeModal();await loadDatabase();render();flash(allow?'Account approved.':'Account access revoked.');
  }
 }catch(err){flash(err.message||'The action could not be completed.',true);}finally{busyForm(form,false);}
}
function exportLedger(){const lines=[['Date','Type','Member','Group','Project','Description','Deposit (PKR)','Expense (PKR)','Status'],...[...db.ledger_entries].map(e=>[e.entry_date,e.kind,mName(e.member_id),gName(e.group_id),pName(e.project_id),e.note,e.kind==='deposit'&&!e.voided_at?(e.amount_paisa/100).toFixed(2):'0.00',e.kind==='expense'&&!e.voided_at?(e.amount_paisa/100).toFixed(2):'0.00',e.voided_at?'Voided':'Recorded'])];const csv=lines.map(row=>row.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(',')).join('\r\n');const b=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download='collective-transactions.csv';a.click();URL.revokeObjectURL(url);}
async function clickAction(action){if(action.startsWith('nav:'))return nav(action.slice(4));if(action==='admin-portal')return adminPortal();if(action==='member-login'){authScreen=true;authView='login';closeModal();return render();}if(action==='switch-admin'){await logout();authScreen=true;authView='login';page='admin';return render();}if(action==='auth:exit'){authScreen=false;authView='login';closeModal();return render();}if(action.startsWith('auth:')){authScreen=true;authView=action.slice(5);closeModal();return render();}if(action==='close')return closeModal();if(action==='logout')return logout();if(action==='check-approval')return checkAuth();if(action.startsWith('group:'))return groupDetails(action.slice(6));if(action.startsWith('member:'))return memberDetails(action.slice(7));if(action.startsWith('tab:')){adminTab=action.slice(4);return nav('admin');}if(action.startsWith('admin:')){adminTab=action.slice(6);return nav('admin');}
 if(action==='setup'){modal('Publish the portal','Firebase configuration required',`<p>See FIREBASE_SETUP.md in the website package.</p>`);return;}
 if(action==='send-reset'){if(!user?.email)return;await auth.sendPasswordResetEmail(user.email);flash('Password reset email sent.');return;}

 if(!isAdmin())return;
 if(action.startsWith('edit-member:'))return editMember(action.slice(12));if(action.startsWith('edit-group:'))return editGroup(action.slice(11));if(action.startsWith('edit-project:'))return editProject(action.slice(13));if(action.startsWith('access:'))return manageAccount(action.slice(7));
 if(action.startsWith('void:')){const entry=action.slice(5),reason=window.prompt('Reason for voiding this entry (minimum 5 characters):');if(reason===null)return;if(reason.trim().length<5){flash('Reason must be at least 5 characters.',true);return;}await runWrite('ledger_entries',{voided_at:new Date().toISOString(),void_reason:reason.trim(),voided_by:user.id},entry);flash('Entry voided.');return;}
 if(action.startsWith('admin-role:')){const id=action.slice(11),p=db.profiles.find(q=>q.user_id===id);if(!p||profile?.role!=='owner'||!p.approved)return flash('Approve the member before granting admin access.',true);const yes=window.confirm(p.role==='admin'?'Remove administrator access?':'Grant this approved account administrator access?');if(!yes)return;await runWrite('users',{role:p.role==='admin'?'member':'admin'},id);flash('Administrator role updated.');return;}
 if(action==='export')return exportLedger();
}
document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(target){e.preventDefault();clickAction(target.dataset.action).catch(err=>flash(err.message,true));}else if(e.target.dataset.overlay==='1')closeModal();});
document.addEventListener('submit',handleFormSubmit);
document.addEventListener('change',e=>{if(e.target.id==='entry-kind'){const n=byId('entry-extra');if(n)n.innerHTML=entryFields(e.target.value);}if(e.target.id==='member-group-filter'){groupFilter=e.target.value;render();}});
document.addEventListener('input',e=>{if(e.target.id==='member-search'){memberSearch=e.target.value;const s=e.target.selectionStart;render();const target=byId('member-search');if(target){target.focus();target.setSelectionRange(s,s);}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});
async function init(){
 if(!connected){role='demo';authShell('<h2>Configuration missing</h2><p>Firebase is not connected. Please contact the website administrator.</p>');return;}
 auth.onAuthStateChanged(async()=>{if(!authInitialized){authInitialized=true;}try{await checkAuth();}catch(e){console.error(e);flash('Authentication error: '+e.message,true);}});
}

init().catch(e=>{console.error(e);flash('Unable to start: '+e.message,true);});
